-- Mnemos Supabase schema contract. Apply explicitly; never embed service-role credentials in agents.
create table if not exists public.memories (id text primary key, workspace_id text not null, kind text not null default 'note', content text not null, tags jsonb not null default '[]'::jsonb check(jsonb_typeof(tags)='array'), source jsonb, metadata jsonb not null default '{}'::jsonb, content_sha256 text not null check(content_sha256 ~ '^[a-fA-F0-9]{64}$'), schema_version integer not null default 1 check(schema_version=1), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.links (id text primary key, workspace_id text not null, source_id text not null, target_id text not null, relation text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,source_id,target_id,relation), foreign key(source_id) references public.memories(id) on delete restrict, foreign key(target_id) references public.memories(id) on delete restrict, check(source_id<>target_id));
create table if not exists public.bundles (id text primary key, workspace_id text not null, schema_version integer not null default 1 check(schema_version=1), memory_count integer not null default 0 check(memory_count>=0), link_count integer not null default 0 check(link_count>=0), content_sha256 text not null check(content_sha256 ~ '^[a-fA-F0-9]{64}$'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists memories_workspace_updated_idx on public.memories(workspace_id,updated_at,id); create index if not exists links_workspace_updated_idx on public.links(workspace_id,updated_at,id); create index if not exists bundles_workspace_updated_idx on public.bundles(workspace_id,updated_at,id);
alter table public.memories enable row level security; alter table public.links enable row level security; alter table public.bundles enable row level security;
drop policy if exists memories_workspace_isolation on public.memories; create policy memories_workspace_isolation on public.memories for all to authenticated using(workspace_id=current_setting('app.workspace_id',true)) with check(workspace_id=current_setting('app.workspace_id',true));
drop policy if exists links_workspace_isolation on public.links; create policy links_workspace_isolation on public.links for all to authenticated using(workspace_id=current_setting('app.workspace_id',true)) with check(workspace_id=current_setting('app.workspace_id',true));
drop policy if exists bundles_workspace_isolation on public.bundles; create policy bundles_workspace_isolation on public.bundles for all to authenticated using(workspace_id=current_setting('app.workspace_id',true)) with check(workspace_id=current_setting('app.workspace_id',true));
grant select,insert,update,delete on public.memories,public.links,public.bundles to authenticated;
